#!/usr/bin/env node
// Sync the frontend's OpenAPI test fixture with the canonical bundled BFF
// document.
//
// The fixture (frontend/src/api/__fixtures__/openapi.json) is a curated,
// ref-inlined mirror of the schemas the UI actually renders. The BFF's
// canonical bundled document (api/openapi/varroa.json) is generated by
// `hack/openapi-bundle`. This script regenerates the fixture's ControllerSpec
// schema from canonical, using the same $ref-resolution the frontend's
// openapiSchema.ts performs at runtime, so the fixture cannot silently stale
// out of step with the contract.
//
// A vitest guard (src/api/openapiFixture.test.ts) fails the suite when the
// fixture drifts from canonical, so regenerating here keeps the guard green.
//
// Usage (from anywhere in the repo):
//   node frontend/scripts/sync-openapi-fixture.mjs

import { readFileSync, writeFileSync } from "node:fs";

const canonicalPath = new URL("../../api/openapi/varroa.json", import.meta.url);
const fixturePath = new URL("../src/api/__fixtures__/openapi.json", import.meta.url);

const canonical = JSON.parse(readFileSync(canonicalPath, "utf8"));
const fixture = JSON.parse(readFileSync(fixturePath, "utf8"));

// ── same logic as frontend/src/api/openapiSchema.ts ────────────────────────
function resolveSchemaRefs(obj, schemas, visited = new Set()) {
  if (!obj || typeof obj !== "object") return obj;
  if (Array.isArray(obj)) return obj.map((item) => resolveSchemaRefs(item, schemas, visited));
  const dict = obj;
  const ref = dict["$ref"];
  if (ref && typeof ref === "string" && ref.startsWith("#")) {
    const parts = ref.replace(/^#\//, "").split("/");
    const name = parts[parts.length - 1];
    if (name && schemas[name] && !visited.has(name)) {
      visited.add(name);
      const out = resolveSchemaRefs(JSON.parse(JSON.stringify(schemas[name])), schemas, visited);
      // Release the name so sibling references to the same schema are also
      // inlined (mirrors openapiSchema.ts); only a true cycle stays raw.
      visited.delete(name);
      return out;
    }
    return obj;
  }
  const result = {};
  for (const [key, value] of Object.entries(dict)) result[key] = resolveSchemaRefs(value, schemas, visited);
  return result;
}

function getNamedSchema(root, name) {
  const schemas = root?.components?.schemas;
  if (!schemas) throw new Error("document has no components.schemas");
  if (!schemas[name]) throw new Error(`document has no ${name} schema`);
  return resolveSchemaRefs(JSON.parse(JSON.stringify(schemas[name])), schemas);
}

// ── regenerate the fixture's ControllerSpec from canonical ─────────────────
const controllerSpec = getNamedSchema(canonical, "ControllerSpec");
if (!fixture.components?.schemas?.ControllerSpec) {
  throw new Error("fixture has no ControllerSpec schema to update");
}
fixture.components.schemas.ControllerSpec = controllerSpec;

writeFileSync(fixturePath, JSON.stringify(fixture, null, 2) + "\n");
console.log(`Synced ${fixturePath.pathname} ControllerSpec from canonical ${canonicalPath.pathname}`);
